img = cv2.imread('input_files/input-01.png')
b,g,r = img[:,:,0].astype(int), img[:,:,1].astype(int), img[:,:,2].astype(int)
black = ((b<110)&(g<110)&(r<110)).astype(np.uint8)*255

def lines(x0,y0,x1,y1,name,minlen=12,gap=3):
    roi = black[y0:y1, x0:x1]
    ls = cv2.HoughLinesP(roi, 1, np.pi/180, threshold=minlen, minLineLength=minlen, maxLineGap=gap)
    H,V = {}, {}
    if ls is None: print(name,'none'); return
    for l in ls[:,0]:
        xa,ya,xb,yb = l
        if abs(ya-yb)<=1:
            y=(ya+yb)//2; H.setdefault(y,[]).append((min(xa,xb),max(xa,xb)))
        elif abs(xa-xb)<=1:
            x=(xa+xb)//2; V.setdefault(x,[]).append((min(ya,yb),max(ya,yb)))
    def merge(d):
        out=[]
        for k in sorted(d):
            segs=sorted(d[k]); s,e=segs[0]
            for a2,b2 in segs[1:]:
                if a2<=e+gap: e=max(e,b2)
                else: out.append((k,s,e)); s,e=a2,b2
            out.append((k,s,e))
        return out
    print(f'--- {name} offset=({x0},{y0})')
    for y,a,b2 in merge(H):
        if b2-a>=minlen: print(f'  H y={y+y0} x:{a+x0}-{b2+x0}')
    for x,a,b2 in merge(V):
        if b2-a>=minlen: print(f'  V x={x+x0} y:{a+y0}-{b2+y0}')

